// Dynamic array allocation and manipulation
int* arr = (int*)malloc(10 * sizeof(int));
if (arr == NULL) { /* Error */ }

// Access via array index or pointer arithmetic
arr[0] = 42;
*(arr + 1) = 99;

// Change size
arr = (int*)realloc(arr, 20 * sizeof(int));

// Deallocate
free(arr);

// Function Definition and Call
int sum(int a, int b) {
    return a + b;
}

// Inline function (C99)
inline int sq(int x) {
    return x * x;
}

int total = sum(5, 7);
int area = sq(total);

// Struct definition, typedef, initialization
typedef struct Person {
    char name[50];
    int age;
} Person_t;

Person_t p1 = {"Alice", 30};
Person_t* p_ptr = &p1;

// Accessing members
p_ptr->age = 31;
(*p_ptr).age += 1;

// Bit fields inside a struct
struct StatusFlags {
    unsigned int is_ready : 1;
    unsigned int error_code : 3;
    unsigned int reserved : 4;
};

// Function Pointers (Callbacks)
int calculate(int (*op)(int, int), int x, int y) {
    return op(x, y);
}

int multiply(int a, int b) {
    return a * b;
}

int (*func_ptr)(int, int) = &multiply;

// Direct call or via helper function
int result = calculate(func_ptr, 6, 4);

// Preprocessor Directives (Macros and Conditionals)
#define BUFFER_SIZE 512
#define DEBUG_MSG(fmt, ...) printf(fmt, ##__VA_ARGS__)

#ifndef RELEASE_BUILD
DEBUG_MSG("Init successful.\n");
#endif

#define SWAP(T, a, b) do { \
    T temp = (a);          \
    (a) = (b);             \
    (b) = temp;            \
} while (0)

int x = 10, y = 20;
SWAP(int, x, y); // x=20, y=10
#undef BUFFER_SIZE
#define BUFFER_SIZE 1024
